import os
import base64

def create_template():
    if not os.path.exists("templates"):
        os.makedirs("templates")
        
    # Base64 encoded Safe Mode HTML (No Emojis, Pure ASCII)
    encoded_html = ""
    
    html_content = base64.b64decode(encoded_html).decode('utf-8')

    with open("templates/index.html", "w", encoding="utf-8") as f:
        f.write(html_content)
    print("✅ Dashboard Template Generated (Safe Mode).")

if __name__ == "__main__":
    create_template()
